import 'package:cephalopod/core/board/models/board_ui.dart';
import 'package:cephalopod/features/how_to_play/presentation/models/tutorial_topic.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'tutorial_step_ui.freezed.dart';

/// One page of How to play as the screen draws it: the [topic] it teaches,
/// which the screen puts into words, and the example [board].
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
abstract class TutorialStepUi with _$TutorialStepUi {
  const factory TutorialStepUi({
    required TutorialTopic topic,
    required BoardUi board,
  }) = _TutorialStepUi;
}
